window.EXAM_CHAPTER_DATA["pol_econ"]["00_导论"] = {"id":"00_导论","name":"导论","kps":[{"id":"KP01","name":"政治经济学的研究对象","file":"教材笔记/07_政治经济学/00_导论/知识点/KP01_政治经济学的研究对象.md","questions":[{"id":"pol_econ_00_导论_KP01_1","num":"1","stem":"马克思主义政治经济学的研究对象是（　）。","options":{"A":"国家财政收支","B":"社会生产关系及其发展规律","C":"稀缺资源的配置","D":"企业利润最大化"},"answer":"B"},{"id":"pol_econ_00_导论_KP01_2","num":"2","stem":"生产关系的基础是（　）。","options":{"A":"产品分配形式","B":"人们在生产中的地位","C":"生产资料所有制","D":"生产力水平"},"answer":"C"},{"id":"pol_econ_00_导论_KP01_3","num":"3","stem":"构成社会经济基础的是（　）。","options":{"A":"一定社会占统治地位的生产关系的总和","B":"社会上层建筑","C":"社会生产力","D":"社会各种法律制度"},"answer":"A"},{"id":"pol_econ_00_导论_KP01_4","num":"4","stem":"下列关于生产力与生产关系关系的说法，正确的是（　）。","options":{"A":"生产关系决定生产力","B":"生产力决定生产关系，生产关系反作用于生产力","C":"两者互不相干","D":"生产关系永远促进生产力发展"},"answer":"B"},{"id":"pol_econ_00_导论_KP01_5","num":"5","stem":"物质资料生产是人类社会存在和发展的（　）。","options":{"A":"唯一活动","B":"前提和基础","C":"附属活动","D":"偶然活动"},"answer":"B"},{"id":"pol_econ_00_导论_KP01_6","num":"6","stem":"政治经济学研究的生产关系是指（　）。","options":{"A":"人们在日常生活中的人际关系","B":"人们在物质资料生产过程中结成的社会关系","C":"企业内部的上下级关系","D":"国与国之间的外交关系"},"answer":"B"},{"id":"pol_econ_00_导论_KP01_7","num":"7","stem":"下列关于\"政治经济学研究的不是物，而是物背后的人与人的关系\"的理解，错误的是（　）。","options":{"A":"商品、货币、资本都是被物的外壳掩盖的社会关系","B":"研究奶茶店不能只研究奶茶怎么制作，还要研究谁占有店面、谁拿利润","C":"这意味着政治经济学不研究任何经济现象","D":"资本不是物，而是一定的社会生产关系"},"answer":"C"},{"id":"pol_econ_00_导论_KP01_8","num":"8","stem":"西方经济学与马克思主义政治经济学在研究对象上的根本区别是（　）。","options":{"A":"西方经济学研究宏观，马克思主义研究微观","B":"西方经济学研究资源配置，马克思主义研究生产关系","C":"西方经济学用数学，马克思主义不用数学","D":"西方经济学研究市场，马克思主义研究计划"},"answer":"B"},{"id":"pol_econ_00_导论_KP01_9","num":"9","stem":"（逻辑链·分析）政治经济学的研究对象是生产关系，其传导链正确的是（　）。","options":{"A":"物质资料生产是出发点 → 生产中人与人的关系即生产关系 → 生产关系包括生产、分配、交换、消费四环节 → 研究生产关系及其发展规律","B":"政治经济学研究物的自然属性","C":"政治经济学研究财富怎么分配","D":"政治经济学研究国家制度"},"answer":"A"},{"id":"pol_econ_00_导论_KP01_10","num":"10","stem":"（逻辑链·判断）生产、分配、交换、消费四环节的关系，正确传导是（　）。","options":{"A":"生产决定分配交换消费的对象和方式，分配交换消费反作用于生产","B":"消费决定生产","C":"分配决定生产","D":"四环节彼此独立"},"answer":"A"}]},{"id":"KP02","name":"政治经济学的研究方法","file":"教材笔记/07_政治经济学/00_导论/知识点/KP02_政治经济学的研究方法.md","questions":[{"id":"pol_econ_00_导论_KP02_1","num":"1","stem":"马克思主义政治经济学的根本方法是（　）。","options":{"A":"数学建模法","B":"唯物辩证法","C":"实验法","D":"问卷调查法"},"answer":"B"},{"id":"pol_econ_00_导论_KP02_2","num":"2","stem":"马克思说\"分析经济形式，既不能用显微镜，也不能用化学试剂，二者都必须用（　）来代替\"。","options":{"A":"抽象力","B":"数学","C":"经验","D":"权威"},"answer":"A"},{"id":"pol_econ_00_导论_KP02_3","num":"3","stem":"科学抽象法的正确路径是（　）。","options":{"A":"从抽象到具体，再从具体到抽象","B":"从感性具体到抽象规定，再从抽象规定到思维中的具体","C":"从概念到概念","D":"从数学公式到现实"},"answer":"B"},{"id":"pol_econ_00_导论_KP02_4","num":"4","stem":"《资本论》从商品开始，然后货币、资本、剩余价值、利润、地租。这种叙述顺序体现的方法是（　）。","options":{"A":"从具体到具体","B":"从抽象上升到具体","C":"从历史到历史","D":"从现象到现象"},"answer":"B"},{"id":"pol_econ_00_导论_KP02_5","num":"5","stem":"逻辑与历史相一致的原则是指（　）。","options":{"A":"逻辑顺序必须与历史事件的时间顺序完全一致","B":"逻辑顺序反映历史发展的本质规律，但撇开历史中的偶然因素","C":"研究经济学不需要历史","D":"历史方法等于逻辑方法"},"answer":"B"},{"id":"pol_econ_00_导论_KP02_6","num":"6","stem":"下列关于科学抽象法的说法，错误的是（　）。","options":{"A":"它是从客观事实出发的思维加工","B":"它和空想一样，都是从愿望出发","C":"它需要\"去粗取精、去伪存真、由此及彼、由表及里\"","D":"它在《资本论》中得到完整运用"},"answer":"B"},{"id":"pol_econ_00_导论_KP02_7","num":"7","stem":"经济学不能像物理学那样在实验室控制变量，是因为（　）。","options":{"A":"经济学家不够聪明","B":"经济过程是由亿万人有意识参与的社会过程，无法隔离重复","C":"经济学不需要精确","D":"物理学比经济学科学"},"answer":"B"},{"id":"pol_econ_00_导论_KP02_8","num":"8","stem":"唯物辩证法在经济学中的运用，要求我们（　）。","options":{"A":"只看经济现象之间的联系","B":"从生产方式的矛盾运动中把握经济规律","C":"把资本主义看成永恒秩序","D":"只做定性描述，不做定量分析"},"answer":"B"},{"id":"pol_econ_00_导论_KP02_9","num":"9","stem":"（逻辑链·分析）马克思研究政治经济学的方法，正确传导是（　）。","options":{"A":"从具体到抽象（从表象材料提炼范畴）→ 从抽象到具体（范畴在思维中重建具体整体）→ 逻辑与历史统一","B":"从抽象到具体再到抽象","C":"纯逻辑推演不看历史","D":"只看历史不抽象"},"answer":"A"},{"id":"pol_econ_00_导论_KP02_10","num":"10","stem":"（逻辑链·判断）\"从抽象上升到具体\"的方法，下列理解正确的是（　）。","options":{"A":"从最简单的经济范畴出发，逐步上升到复杂整体，在思维中再现具体","B":"从具体事实直接归纳结论","C":"从理论套用到现实","D":"从数学公式出发"},"answer":"A"}]},{"id":"KP03","name":"政治经济学的创立与发展","file":"教材笔记/07_政治经济学/00_导论/知识点/KP03_政治经济学的创立与发展.md","questions":[{"id":"pol_econ_00_导论_KP03_1","num":"1","stem":"马克思主义政治经济学的直接理论来源是（　）。","options":{"A":"德国古典哲学和英国古典政治经济学","B":"法国庸俗经济学","C":"美国新制度经济学","D":"历史学派"},"answer":"A"},{"id":"pol_econ_00_导论_KP03_2","num":"2","stem":"马克思的两大发现是（　）。","options":{"A":"辩证法和唯物主义","B":"唯物史观和剩余价值学说","C":"劳动价值论和剩余价值论","D":"阶级斗争和无产阶级专政"},"answer":"B"},{"id":"pol_econ_00_导论_KP03_3","num":"3","stem":"古典政治经济学无法解释利润来源，是因为他们（　）。","options":{"A":"没有发现劳动价值论","B":"分不清\"劳动\"和\"劳动力\"","C":"认为资本不创造价值","D":"认为工人没有创造价值"},"answer":"B"},{"id":"pol_econ_00_导论_KP03_4","num":"4","stem":"《资本论》第一卷出版于（　）。","options":{"A":"1848 年","B":"1859 年","C":"1867 年","D":"1883 年"},"answer":"C"},{"id":"pol_econ_00_导论_KP03_5","num":"5","stem":"列宁对马克思主义政治经济学的发展主要体现在（　）。","options":{"A":"提出科学社会主义","B":"研究垄断资本主义，写成《帝国主义是资本主义的最高阶段》","C":"提出劳动价值论","D":"创立剩余价值学说"},"answer":"B"},{"id":"pol_econ_00_导论_KP03_6","num":"6","stem":"空想社会主义与科学社会主义的根本区别是（　）。","options":{"A":"空想社会主义不主张社会主义","B":"空想社会主义凭道德愤怒，科学社会主义从经济规律论证资本主义必然灭亡","C":"空想社会主义是德国人提出的","D":"科学社会主义不关心工人利益"},"answer":"B"},{"id":"pol_econ_00_导论_KP03_7","num":"7","stem":"下列关于马克思主义政治经济学发展的说法，错误的是（　）。","options":{"A":"它是开放的、发展的理论","B":"中国特色社会主义政治经济学是它在当代中国的发展","C":"它一经创立就不再变化","D":"习近平新时代中国特色社会主义经济思想是它的最新成果"},"answer":"C"},{"id":"pol_econ_00_导论_KP03_8","num":"8","stem":"马克思批判西尼尔的\"节欲论\"，认为资本积累的动因是（　）。","options":{"A":"资本家的道德节俭","B":"追求剩余价值的内在贪欲和竞争的外在压力","C":"国家的鼓励","D":"工人的要求"},"answer":"B"},{"id":"pol_econ_00_导论_KP03_9","num":"9","stem":"（逻辑链·分析）马克思主义政治经济学的创立，正确传导是（　）。","options":{"A":"古典政治经济学提出劳动价值论但有局限 → 马克思批判继承 → 创立劳动二重性学说和剩余价值理论 → 政治经济学发生革命变革","B":"马克思凭空创造","C":"马克思全盘否定古典政治经济学","D":"马克思继承了庸俗经济学"},"answer":"A"},{"id":"pol_econ_00_导论_KP03_10","num":"10","stem":"（逻辑链·判断）马克思在政治经济学史上的伟大发现是（　）。","options":{"A":"劳动二重性学说和剩余价值理论","B":"劳动价值论","C":"剩余价值论是马克思第一个提出的","D":"货币数量论"},"answer":"A"}]}]};
